DROP TRIGGER IF EXISTS lots_no_negative_ins ON lots;
CREATE TRIGGER lots_no_negative_ins BEFORE INSERT ON lots FOR EACH ROW EXECUTE FUNCTION ftz_lots_no_negative_ins();
